    "cmd": "python -c \"with open('data/sensor_panel_timeseries.csv', 'r') as f: lines = f.readlines(); print(f'Total lines: {len(lines)}'); print('First 5 lines:'); [print(repr(l)) for l in lines[:5]]\""
